function filtered(){return records.filter(r=>(!groupFilter||((!groupFilter.flow||r.type===groupFilter.flow)&&groupFilter.objects.includes(r.object||'Não informado')))&&(!$('from').value||r.date>=$('from').value)&&(!$('to').value||r.date<=$('to').value)&&(!$('category').value||r.category===$('category').value)&&(!$('object').value||r.object===$('object').value)&&(!$('type').value||r.type===$('type').value)&&(!$('search').value||[r.description,r.category,r.object,r.method,publicLabel(r.description),publicLabel(r.object)].join(' ').toLocaleLowerCase('pt-BR').includes($('search').value.toLocaleLowerCase('pt-BR'))));}
