function balLedgerTextHeight(desc){
 const safe=String(desc||'');const approxPerLine=70;
 const lines=Math.max(1,Math.ceil(safe.length/approxPerLine));
 return lines>=3?.60:lines===2?.47:.35;
}
function balAddLedgerSlides(pptx,keys){
 const costMap=new Map(costData().map(row=>[row.key,row]));
 for(const key of keys){
  const entries=records.filter(r=>r.date.slice(0,7)===key).sort((a,b)=>a.date.localeCompare(b.date)||a.id-b.id);
  let chunks=[],curr=[],used=0;
  for(const item of entries){const rowH=balLedgerTextHeight(publicLabel(item.description));if(curr.length && used+rowH>4.63){chunks.push(curr);curr=[];used=0;}curr.push([item,rowH]);used+=rowH;}
  if(curr.length||!chunks.length)chunks.push(curr);
  const monthResult=costMap.get(key)||{in:0,out:0,cash:0};
  for(let page=0;page<chunks.length;page++){
   const slide=pptx.addSlide();slide.background={color:balSlideColors.white};const monthTitle=balMonthName(key);
   balSlideHeader(pptx,slide,monthTitle+(chunks.length>1?` — Parte ${page+1}/${chunks.length}`:''),`Movimentações detalhadas · ${chunks[page].length} lançamentos nesta página`);
   const x=.65,y=1.52,ww=[7.0,2.0,1.52,1.52],titleH=.44;
   const titles=['Tipo','Data','Entrada','Saída'],headColors=[balSlideColors.orangeLite,balSlideColors.orangeLite,balSlideColors.green,balSlideColors.red];
   let xx=x;for(let c=0;c<4;c++){balSlideRect(slide,xx,y,ww[c],titleH,headColors[c],balSlideColors.ink,1.65);balSlideText(slide,titles[c],xx+.09,y+.02,ww[c]-.18,titleH-.04,{size:17,bold:true,align:c<2?'left':'center'});xx+=ww[c];}
   let pos=y+titleH;
   for(const [r,rowH] of chunks[page]){
    const cells=[publicLabel(r.description||'Movimentação'),balDateISO(r.date),r.type==='Entrada'?balMoney(r.value):'—',r.type==='Gasto'?balMoney(r.value):'—'];
    const colors=[balSlideColors.cream,balSlideColors.cream,balSlideColors.greenLite,balSlideColors.redLite];let left=x;
    for(let c=0;c<4;c++){
     balSlideRect(slide,left,pos,ww[c],rowH,colors[c],balSlideColors.ink,.85);
     balSlideText(slide,cells[c],left+.075,pos+.01,ww[c]-.15,rowH-.025,{size:c===0?12.3:13.4,bold:c>=2 &&cells[c]!=='—',align:c===0?'left':c===1?'center':'right',color:c===2?'28623C':c===3?'A02C33':'171717'});
     left+=ww[c];
    }
    pos+=rowH;
   }
   if(page===chunks.length-1){
    const footerY=Math.min(6.88,Math.max(pos+.16,6.53));
    balSlideRect(slide,x,footerY,ww[0]+ww[1],.38,balSlideColors.orangeLite,balSlideColors.ink,1.7);
    balSlideRect(slide,x+ww[0]+ww[1],footerY,ww[2]+ww[3],.38,balSlideColors.cream,balSlideColors.ink,1.7);
    balSlideText(slide,`Caixa final ${monthTitle}`,x+.1,footerY+.025,ww[0]+ww[1]-.2,.33,{size:16,bold:true,align:'center'});
    balSlideText(slide,balMoney(monthResult.cash),x+ww[0]+ww[1]+.1,footerY+.025,ww[2]+ww[3]-.2,.33,{size:16,bold:true,align:'right'});
   }
   balSlideFooter(slide,`Entradas: ${balMoney(monthResult.in)} · Saídas: ${balMoney(monthResult.out)} · ${entries.length} lançamentos no mês · CAHS`);
  }
 }
}
async function balGenerateSlides(){
 const keys=[...document.querySelectorAll('#balancete-month-list input[name="bal-month"]:checked')].map(x=>x.value).sort();
 if(!keys.length)return;
 if(typeof PptxGenJS!=='function'){alert('Não foi possível iniciar o gerador de slides. Abra a versão completa do arquivo HTML e tente novamente.');return;}
 const button=$('balancete-create'),caption=button.textContent;
 button.disabled=true;button.textContent='Preparando slides…';
 try{
  const pptx=new PptxGenJS();pptx.layout='LAYOUT_WIDE';pptx.author='Centro Acadêmico Herbert de Sousa (CAHS)';pptx.subject='Balancete financeiro do CAHS';pptx.title='Balancete CAHS — '+keys.map(balMonthName).join(', ');pptx.lang='pt-BR';pptx.theme={headFontFace:'Aptos Display',bodyFontFace:'Aptos',lang:'pt-BR'};
  balAddGraphSlide(pptx,keys,'cash');balAddGraphSlide(pptx,keys,'flows');balAddCostsSlides(pptx,keys);balAddLedgerSlides(pptx,keys);
  const name=`Balancete_CAHS_${keys[0]}_a_${keys.at(-1)}.pptx`;
  await pptx.writeFile({fileName:name,compression:true});
  $('balancete-dialog').close();
 }catch(e){console.error('Erro ao gerar balancete PowerPoint',e);alert('Não foi possível gerar o PowerPoint: '+(e?.message||e));}
 finally{button.disabled=false;button.textContent=caption;}
}

// Emissão de balancetes: exclusivamente os meses selecionados, usando a base financeira pública incorporada.
const balFullMonthNames=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const balMoney=value=>money(Math.round(value));
const balMonthName=key=>{const [year,mo]=key.split('-').map(Number);return `${balFullMonthNames[mo-1].charAt(0).toUpperCase()+balFullMonthNames[mo-1].slice(1)} de ${year}`;};
const balMonthOnly=key=>{const mo=Number(key.split('-')[1]);return balFullMonthNames[mo-1].charAt(0).toUpperCase()+balFullMonthNames[mo-1].slice(1);};
const balDateISO=dateStr=>dateStr.split('-').reverse().join('/');
const balDaysInMonth=monthKey=>{const [y,m]=monthKey.split('-').map(Number);return new Date(Date.UTC(y,m,0)).getUTCDate();};
const balDatePlus1=d=>{const [y,m,day]=d.split('-').map(Number);const next=new Date(Date.UTC(y,m-1,day+1));return next.toISOString().slice(0,10);};
function balGetMonths(){return [...new Set(records.map(r=>r.date.slice(0,7)))].sort();}
function balOpenPicker(){
 const available=balGetMonths(),last=available.slice(-3),dialog=$('balancete-dialog'),list=$('balancete-month-list');
 list.innerHTML=available.map(key=>`<label class="bal-month-choice"><input type="checkbox" name="bal-month" value="${key}" ${last.includes(key)?'checked':''}><span>${esc(balMonthName(key))}</span></label>`).join('');
 const update=()=>{const count=dialog.querySelectorAll('input[name="bal-month"]:checked').length;$('balancete-selection-note').textContent=count===1?'1 mês selecionado':`${count} meses selecionados`;$('balancete-create').disabled=count===0;};
 list.onchange=update;
 update();dialog.showModal();
}
function balSmooth(points){
 if(!points.length)return '';
 if(points.length===1)return `M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`;
 let path=`M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`;
 for(let i=0;i<points.length-1;i++){
   const prev=points[Math.max(0,i-1)],p=points[i],n=points[i+1],after=points[Math.min(points.length-1,i+2)];
   const dx=(n.x-p.x)*.33;
   // Tangentes moderadas: mantém o caráter suave da referência sem oscilações excessivas.
   const ySlope1=(n.y-prev.y)/(n.x-prev.x||1),ySlope2=(after.y-p.y)/(after.x-p.x||1);
   const c1y=Math.max(Math.min(p.y+dx*ySlope1,Math.max(p.y,n.y)+10),Math.min(p.y,n.y)-10);
   const c2y=Math.max(Math.min(n.y-dx*ySlope2,Math.max(p.y,n.y)+10),Math.min(p.y,n.y)-10);
   path+=` C ${(p.x+dx).toFixed(2)} ${c1y.toFixed(2)} ${(n.x-dx).toFixed(2)} ${c2y.toFixed(2)} ${n.x.toFixed(2)} ${n.y.toFixed(2)}`;
 }
 return path;
}
function balTimeline(keys){
 const include=new Set(keys),all=records.slice().sort((a,b)=>a.date.localeCompare(b.date)||a.id-b.id),lastDay=`${keys.at(-1)}-${String(balDaysInMonth(keys.at(-1))).padStart(2,'0')}`;
 const flows=new Map();all.forEach(r=>{const entry=flows.get(r.date)||{incoming:0,outgoing:0};entry[r.type==='Entrada'?'incoming':'outgoing']+=r.value;flows.set(r.date,entry);});
 let d=`${keys[0]}-01`,running=all.filter(r=>r.date<d).reduce((v,r)=>v+signed(r),0);const points=[];
 while(d<=lastDay){const day=flows.get(d)||{incoming:0,outgoing:0};running+=day.incoming-day.outgoing;if(include.has(d.slice(0,7)))points.push({date:d,balance:running,inc:day.incoming,out:day.outgoing});d=balDatePlus1(d);}
 return points;
}
function balChartSvg(timeline,kind){
 const W=1480,H=760,left=138,right=30,top=34,bottom=98,PW=W-left-right,PH=H-top-bottom;
 const cash=kind==='cash';
 const smooth=(index,flow)=>{let amount=0,n=0;for(let i=index-2;i<=index+2;i++){if(i>=0&&i<timeline.length&&timeline[i].date.slice(0,7)===timeline[index].date.slice(0,7)){amount+=timeline[i][flow];n++;}}return amount/(n||1);};
 const cashValues=timeline.map(x=>Math.max(0,x.balance));
 const inValues=timeline.map((_,i)=>smooth(i,'inc'));
 const outValues=timeline.map((_,i)=>smooth(i,'out'));
 const allValues=cash?cashValues:[...inValues,...outValues];
 const maxVal=Math.max(1,...allValues);
 const topVal=Math.ceil((maxVal*1.12)/500)*500;
 const xAt=i=>left+(timeline.length===1?PW/2:i/(timeline.length-1)*PW),yAt=v=>top+(topVal-v)/topVal*PH;
 const horizontal=[];
 for(let i=0;i<=4;i++){
  const val=topVal*(4-i)/4,y=yAt(val);
  horizontal.push(`<line x1="${left}" y1="${y.toFixed(2)}" x2="${W-right}" y2="${y.toFixed(2)}" stroke="#d7d7d1" stroke-width="2"/><text x="${left-18}" y="${(y+7).toFixed(2)}" text-anchor="end" class="bal-axis-y">${esc(balMoney(val))}</text>`);
 }
 const tickSet=new Set();
 for(let i=0;i<timeline.length;i++) if(i===0||timeline[i].date.slice(0,7)!==timeline[i-1].date.slice(0,7)) tickSet.add(i);
 if(timeline.length>1) tickSet.add(timeline.length-1);
 const vertical=[...tickSet].sort((a,b)=>a-b).map(i=>{const x=xAt(i),label=balDateISO(timeline[i].date);return `<line x1="${x.toFixed(2)}" y1="${top}" x2="${x.toFixed(2)}" y2="${top+PH}" stroke="#d6d6d1" stroke-width="2"/><text x="${x.toFixed(2)}" y="${H-26}" text-anchor="middle" class="bal-axis-x">${label}</text>`;}).join('');
 let series='';
 if(cash){
   const pts=cashValues.map((v,i)=>({x:xAt(i),y:yAt(v)}));
   const path=balSmooth(pts);
   const area=`${path} L ${pts.at(-1).x.toFixed(2)} ${(top+PH).toFixed(2)} L ${pts[0].x.toFixed(2)} ${(top+PH).toFixed(2)} Z`;
   series+=`<path d="${area}" fill="#f4e5ab" opacity="0.85"/><path d="${path}" stroke="#ddb84d" stroke-width="5" fill="none" stroke-linecap="round"/>`;
   const labelIdx=[0,Math.floor((timeline.length-1)*0.33),Math.floor((timeline.length-1)*0.52),Math.floor((timeline.length-1)*0.70),Math.floor((timeline.length-1)*0.86),timeline.length-1].filter((v,i,a)=>a.indexOf(v)===i && v>=0 && v<timeline.length);
   series+=labelIdx.map(i=>{const x=xAt(i),y=yAt(cashValues[i]);return `<text x="${x.toFixed(2)}" y="${(y-16).toFixed(2)}" text-anchor="middle" class="bal-point-label">${esc(balMoney(cashValues[i]))}</text>`;}).join('');
 } else {
   const mk=(vals,color)=>{const pts=vals.map((v,i)=>({x:xAt(i),y:yAt(v)}));return `<path d="${balSmooth(pts)}" stroke="${color}" stroke-width="5" fill="none" stroke-linecap="round"/>`;};
   series+=mk(inValues,'#62b26f')+mk(outValues,'#d06056');
   series+=`<g><rect x="630" y="34" width="24" height="7" fill="#62b26f" rx="2"/><text x="666" y="45" class="bal-legend-text">Entradas</text><rect x="760" y="34" width="24" height="7" fill="#d06056" rx="2"/><text x="796" y="45" class="bal-legend-text">Saídas</text></g>`;
 }
 return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${cash?'Gráfico da evolução do caixa':'Gráfico comparativo de entradas e saídas'}" xmlns="http://www.w3.org/2000/svg"><style>.bal-axis-y{font:italic 700 32px Georgia,serif;fill:#5b8b54}.bal-axis-x{font:700 30px Calibri,Arial,sans-serif;fill:#8f322f}.bal-legend-text{font:700 28px Calibri,Arial,sans-serif;fill:#3c3c39}.bal-point-label{font:700 30px Calibri,Arial,sans-serif;fill:#76ae75}</style><rect x="1" y="1" width="1478" height="758" fill="#f3f3f0" stroke="#111" stroke-width="4"/>${horizontal.join('')}${vertical}${series}<line x1="${left}" y1="${top}" x2="${left}" y2="${top+PH}" stroke="#333" stroke-width="4"/><line x1="${left}" y1="${(top+PH).toFixed(2)}" x2="${W-right}" y2="${(top+PH).toFixed(2)}" stroke="#777" stroke-width="3"/></svg>`;
}
function balCostTables(keys){
 const values=costData(),byKey=new Map(values.map(x=>[x.key,x])),chunks=[];
 for(let i=0;i<keys.length;i+=3)chunks.push(keys.slice(i,i+3));
 return chunks.map(group=>{
  const col1=40, rem=(60/group.length).toFixed(3);
  const tableRows=costRows.map(([key,label,klass])=>`<tr class="${klass||''}"><th scope="row">${esc(label)}</th>${group.map(month=>`<td>${balMoney(byKey.get(month)?.[key]||0)}</td>`).join('')}</tr>`).join('');
  return `<section class="bal-print-sheet bal-cost-sheet"><table class="bal-cost-table"><colgroup><col style="width:${col1}%">${group.map(()=>`<col style="width:${rem}%">`).join('')}</colgroup><thead><tr><th>Centro de custo</th>${group.map(m=>`<th>${esc(month(m))}</th>`).join('')}</tr></thead><tbody>${tableRows}</tbody></table></section>`;
 }).join('');
}
// Consolidação exclusiva do balancete: agrupa movimentos do MESMO objeto dentro de cada mês.
// A base de movimentações do portal permanece intacta. Os valores estão em centavos.
function balConsolidateMonthRows(monthRows){
 const buckets=new Map();
 for(const item of monthRows){
  const object=(item.object||'Não informado').trim()||'Não informado';
  if(!buckets.has(object))buckets.set(object,{label:publicLabel(object),date:'Mês inteiro',inc:0,out:0,count:0,firstDate:item.date});
  const group=buckets.get(object);
  group[item.type==='Entrada'?'inc':'out']+=item.value;
  group.count++;
  if(item.date<group.firstDate)group.firstDate=item.date;
 }
 const grouped=[...buckets.values()].sort((a,b)=>a.firstDate.localeCompare(b.firstDate)||a.label.localeCompare(b.label,'pt-BR'));
 // Cada centavo dos lançamentos originais deve aparecer no total consolidado.
 const original=totals(monthRows);
 const after=grouped.reduce((sum,g)=>({in:sum.in+g.inc,out:sum.out+g.out}),{in:0,out:0});
 if(original.in!==after.in||original.out!==after.out)throw new Error('Divergência na consolidação das movimentações mensais.');
 return grouped;
}
function balMonthlyLedger(keys){
 const sorted=records.slice().sort((a,b)=>a.date.localeCompare(b.date)||a.id-b.id),overall=costData(),monthTotals=new Map(overall.map(m=>[m.key,m]));
 const chunkSize=12;
 return keys.map(key=>{
  const entries=balConsolidateMonthRows(sorted.filter(r=>r.date.slice(0,7)===key)),monthLabel=balMonthOnly(key),total=monthTotals.get(key),closing=total?.cash||0;
  const chunks=[];for(let i=0;i<entries.length;i+=chunkSize)chunks.push(entries.slice(i,i+chunkSize));if(!chunks.length)chunks.push([]);
  return chunks.map((chunk,idx)=>{
   const rows=chunk.map(r=>`<tr><td class="bal-type">${esc(r.label||'Não informado')}</td><td class="bal-date">Mês inteiro</td><td class="bal-entry">${r.inc?balMoney(r.inc):'-'}</td><td class="bal-exit">${r.out?balMoney(r.out):'-'}</td></tr>`).join('');
   const footer=idx===chunks.length-1?`<tfoot><tr class="bal-ledger-total"><th colspan="2">Caixa Final ${esc(monthLabel)}</th><th colspan="2">${balMoney(closing)}</th></tr></tfoot>`:'';
   return `<section class="bal-print-sheet bal-month-sheet"><table class="bal-ledger-table"><colgroup><col style="width:46%"><col style="width:18%"><col style="width:18%"><col style="width:18%"></colgroup><thead><tr><th class="bal-month-banner" colspan="4">${esc(monthLabel)}</th></tr><tr class="bal-ledger-heading"><th>Tipo</th><th>Data</th><th>Entrada</th><th>Saída</th></tr></thead><tbody>${rows||'<tr><td class="bal-type" colspan="4">Nenhuma movimentação.</td></tr>'}</tbody>${footer}</table></section>`;
  }).join('');
 }).join('');
}
