// Dados financeiros públicos: JSON externo, com fallback para a versão incorporada.
async function carregarMovimentacoesPublicas(){
 const reserva=JSON.parse($('cahs-data').textContent);
 const status=$('sync-status');
 try{
  const resposta=await fetch('./movimentacoes.json',{cache:'no-store'});
  if(!resposta.ok)throw new Error('HTTP '+resposta.status);
  const pacote=await resposta.json();
  const dados=Array.isArray(pacote)?pacote:pacote.records;
  if(!Array.isArray(dados)||dados.length<Math.min(15,reserva.length))throw new Error('Dados públicos ausentes ou incompletos');
  const ids=new Set();
  for(const r of dados){
   if(!Number.isInteger(r.id)||ids.has(r.id)||!['Entrada','Gasto'].includes(r.type)||
      !/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isInteger(r.value)||r.value<0||
      typeof r.description!=='string'||typeof r.category!=='string'||typeof r.object!=='string')
     throw new Error('Registro público inválido');
   ids.add(r.id);
  }
  if(pacote&&Array.isArray(pacote.caixa)&&pacote.caixa.length===currentCashAllocation.length&&
     pacote.caixa.every(x=>Number.isInteger(x.value)&&x.value>=0)){
   pacote.caixa.forEach((c,i)=>{currentCashAllocation[i].value=c.value;});
   currentCashTotal=currentCashAllocation.reduce((n,x)=>n+x.value,0);
  }
  if(status){
   if(pacote.updatedAt&&!Number.isNaN(Date.parse(pacote.updatedAt))){
    const quando=new Date(pacote.updatedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'});
    status.textContent='Sincronização da planilha: '+quando;
   }else status.textContent='Base pública disponível; sincronização automática aguardando configuração';
  }
  return dados;
 }catch(erro){
  console.warn('O portal continuará com a última base incorporada.',erro);
  if(status)status.textContent='Base incorporada no site · sincronização automática indisponível';
  return reserva;
 }
}

