function drawTeamConnections(){
 const layout=document.querySelector('.team-layout'),svg=layout.querySelector('.team-connections'),base=layout.getBoundingClientRect();
 const box=el=>{const r=el.getBoundingClientRect();return {left:r.left-base.left,right:r.right-base.left,top:r.top-base.top,bottom:r.bottom-base.top,cx:(r.left+r.right)/2-base.left,cy:(r.top+r.bottom)/2-base.top};};
 const advisers=[...layout.querySelectorAll('.team-advisers .team-person')].map(box),leaders=[...layout.querySelectorAll('.team-leaders .team-photo')].map(box);
 if(advisers.length<2||leaders.length!==2||!base.width)return;
 const rowTop=Math.min(...advisers.map(r=>r.cy));
 const upper=advisers.filter(r=>Math.abs(r.cy-rowTop)<30),lower=advisers.filter(r=>r.cy>rowTop+30);
 const middle=lower.length?(Math.max(...upper.map(r=>r.bottom))+Math.min(...lower.map(r=>r.top)))/2:advisers.reduce((sum,r)=>sum+r.cy,0)/advisers.length;
 const leadersGroup=box(layout.querySelector('.team-leaders')),adviserGroup=box(layout.querySelector('.team-advisers')),fork=(leadersGroup.right+adviserGroup.left)/2;
 const paths=[`M${fork},${middle}H${Math.max(...advisers.map(r=>r.cx))}`,`M${fork},${Math.min(middle,...leaders.map(r=>r.cy))}V${Math.max(middle,...leaders.map(r=>r.cy))}`];
 leaders.forEach(r=>paths.push(`M${r.right+6},${r.cy}H${fork}`));
 advisers.forEach(r=>paths.push(`M${r.cx},${r.cy<middle?r.bottom+3:r.top-3}V${middle}`));
 svg.setAttribute('viewBox',`0 0 ${base.width} ${base.height}`);svg.innerHTML=paths.map(d=>`<path d="${d}"/>`).join('');
}
requestAnimationFrame(drawTeamConnections);
if(typeof ResizeObserver!=='undefined')new ResizeObserver(drawTeamConnections).observe(document.querySelector('.team-layout'));
window.addEventListener('resize',drawTeamConnections);
if(document.fonts)document.fonts.ready.then(drawTeamConnections);


function animateCash(total){
 const node=$('currentcash');node.setAttribute('aria-label',money(total));
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){node.textContent=money(total);return;}
 // 5,5 s no total. A primeira fase freia progressivamente; os últimos
 // centavos sobem individualmente, em passos visíveis, sem ultrapassar o saldo.
 const duration=5500,centavoPhase=1050,mainPhase=duration-centavoPhase;
 const cents=total>=0?Math.min(42,Math.round(total)):0;
 const lastStart=total-cents;
 const start=performance.now();let lastValue=null;
 node.textContent=money(0);
 function frame(now){
  const elapsed=Math.max(0,Math.min(duration,now-start));
  let value;
  if(elapsed<mainPhase){
   const p=elapsed/mainPhase;
   const easing=1-Math.pow(1-p,3.25); // desaceleração contínua
   value=Math.round(lastStart*easing);
  }else{
   // Cada centavo progride na reta final — 42 passos em 1,05 segundo.
   const p=Math.min(1,(elapsed-mainPhase)/centavoPhase);
   const centavoEasing=1-Math.pow(1-p,2); // centavos também desaceleram
   value=lastStart+Math.min(cents,Math.floor(centavoEasing*cents));
  }
  if(value!==lastValue){node.textContent=money(value);lastValue=value;}
  if(elapsed<duration)requestAnimationFrame(frame);
  else node.textContent=money(total);
 }
 requestAnimationFrame(frame);
}
function updateRelativeTime(){
 const node=$('last-update');if(!node||!records.length)return;
 const latest=records.reduce((last,r)=>r.date>last?r.date:last,'');
 const movement=new Date(latest+'T00:00:00');if(Number.isNaN(movement.getTime()))return;
 const current=new Date();
 const today=new Date(current.getFullYear(),current.getMonth(),current.getDate());
 const lastDay=new Date(movement.getFullYear(),movement.getMonth(),movement.getDate());
 const days=Math.max(0,Math.round((Date.UTC(today.getFullYear(),today.getMonth(),today.getDate())-Date.UTC(lastDay.getFullYear(),lastDay.getMonth(),lastDay.getDate()))/86400000));
 node.dateTime=latest;
 node.textContent=days===0?'Última movimentação registrada hoje':`Última movimentação registrada há ${days} ${days===1?'dia':'dias'}`;
 node.title='Movimentação mais recente: '+date(latest)+'. A base registra a data, mas não o horário; a diferença considera dias de calendário.';
}
function setupBlockMotion(){
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(reduced||!('IntersectionObserver' in window))return;
 const boxes=[...document.querySelectorAll('.balance-hero, .metrics .metric, .chartgrid > .panel, .insight, .cashpanel, .cashdetails, .case-entry, .resources-grid > .panel, .finance-team')];
 const obs=new IntersectionObserver(entries=>entries.forEach(entry=>{
   if(entry.isIntersecting){entry.target.classList.add('block-visible');obs.unobserve(entry.target);}
 }),{threshold:.07,rootMargin:'0px 0px 30px 0px'});
 boxes.forEach((box,i)=>{
   box.classList.add('block-reveal');
   box.style.setProperty('--block-delay',Math.min((i%4)*65,195)+'ms');
   obs.observe(box);
 });
}
updateRelativeTime();setInterval(updateRelativeTime,60000);

